#ifndef WOLFSSL_SP_NO_256
/* Point structure to use. */
typedef struct sp_point_256 {
    /* X ordinate of point. */
    sp_digit x[2 * 4];
    /* Y ordinate of point. */
    sp_digit y[2 * 4];
    /* Z ordinate of point. */
    sp_digit z[2 * 4];
    /* Indicates point is at infinity. */
    int infinity;
} sp_point_256;
/* A table entry for pre-computed points. */
typedef struct sp_table_entry_256 {
    sp_digit x[4];
    sp_digit y[4];
} sp_table_entry_256;

#endif
#ifdef WOLFSSL_SP_384
/* Point structure to use. */
typedef struct sp_point_384 {
    /* X ordinate of point. */
    sp_digit x[2 * 6];
    /* Y ordinate of point. */
    sp_digit y[2 * 6];
    /* Z ordinate of point. */
    sp_digit z[2 * 6];
    /* Indicates point is at infinity. */
    int infinity;
} sp_point_384;
/* A table entry for pre-computed points. */
typedef struct sp_table_entry_384 {
    sp_digit x[6];
    sp_digit y[6];
} sp_table_entry_384;

#endif
#ifdef WOLFSSL_SP_521
/* Point structure to use. */
typedef struct sp_point_521 {
    /* X ordinate of point. */
    sp_digit x[2 * 9];
    /* Y ordinate of point. */
    sp_digit y[2 * 9];
    /* Z ordinate of point. */
    sp_digit z[2 * 9];
    /* Indicates point is at infinity. */
    int infinity;
#ifdef SP_ALIGN_16
    byte pad[16-sizeof(int)];
#endif
} sp_point_521;
/* A table entry for pre-computed points. */
typedef struct sp_table_entry_521 {
    sp_digit x[9];
    sp_digit y[9];
} sp_table_entry_521;

#endif
#ifdef WOLFSSL_SP_1024
/* Point structure to use. */
typedef struct sp_point_1024 {
    /* X ordinate of point. */
    sp_digit x[2 * 16];
    /* Y ordinate of point. */
    sp_digit y[2 * 16];
    /* Z ordinate of point. */
    sp_digit z[2 * 16];
    /* Indicates point is at infinity. */
    int infinity;
} sp_point_1024;
/* A table entry for pre-computed points. */
typedef struct sp_table_entry_1024 {
    sp_digit x[16];
    sp_digit y[16];
} sp_table_entry_1024;


#endif
