    rax = (word64)(WC_L64(rsi, 24));
    WC_X64I_MUL128(rax, rdx, rax, WC_L64(rsi, 0));
    r9 = (word64)(0);
    cf = _addcarry_u64(0, rcx, rax, (unsigned long long*)&rcx);
    cf = _addcarry_u64(cf, r8, rdx, (unsigned long long*)&r8);
