    rdx = (word64)(WC_L64(r8, 32));
    r9 = (r9 & ~(word64)0xff) | ((word64)(byte)((byte)(cf)) & 0xff);
    WC_S64(r8, 24) = (word64)(rax);
    rdx = (word64)(rdx ^ rcx);
    cf = _addcarry_u64(0, rdx, r9, (unsigned long long*)&rdx);
    rax = (word64)(WC_L64(r8, 40));
    r9 = (r9 & ~(word64)0xff) | ((word64)(byte)((byte)(cf)) & 0xff);
    WC_S64(r8, 32) = (word64)(rdx);
    rax = (word64)(rax ^ rcx);
    cf = _addcarry_u64(0, rax, r9, (unsigned long long*)&rax);
    rdx = (word64)(WC_L64(r8, 48));
    r9 = (r9 & ~(word64)0xff) | ((word64)(byte)((byte)(cf)) & 0xff);
    WC_S64(r8, 40) = (word64)(rax);
    rdx = (word64)(rdx ^ rcx);
    cf = _addcarry_u64(0, rdx, r9, (unsigned long long*)&rdx);
    rax = (word64)(WC_L64(r8, 56));
    r9 = (r9 & ~(word64)0xff) | ((word64)(byte)((byte)(cf)) & 0xff);
    WC_S64(r8, 48) = (word64)(rdx);
    rax = (word64)(rax ^ rcx);
    cf = _addcarry_u64(0, rax, r9, (unsigned long long*)&rax);
    rdx = (word64)(WC_L64(r8, 64));
    r9 = (r9 & ~(word64)0xff) | ((word64)(byte)((byte)(cf)) & 0xff);
    WC_S64(r8, 56) = (word64)(rax);
    rdx = (word64)(rdx ^ rcx);
    cf = _addcarry_u64(0, rdx, r9, (unsigned long long*)&rdx);
    rax = (word64)(WC_L64(r8, 72));
    r9 = (r9 & ~(word64)0xff) | ((word64)(byte)((byte)(cf)) & 0xff);
    WC_S64(r8, 64) = (word64)(rdx);
    rax = (word64)(rax ^ rcx);
    cf = _addcarry_u64(0, rax, r9, (unsigned long long*)&rax);
    rdx = (word64)(WC_L64(r8, 80));
