    rdx = (word64)(WC_L64(rdi, 48));
    WC_S64(rdi, 40) = (word64)(rcx);
    cf = _subborrow_u64(cf, rdx, WC_L64(rsi, 48), (unsigned long long*)&rdx);
    rcx = (word64)(WC_L64(rdi, 56));
    WC_S64(rdi, 48) = (word64)(rdx);
    cf = _subborrow_u64(cf, rcx, WC_L64(rsi, 56), (unsigned long long*)&rcx);
    rdx = (word64)(WC_L64(rdi, 64));
    WC_S64(rdi, 56) = (word64)(rcx);
