    rcx = (word64)(WC_L64(rdi, 88));
    WC_S64(rdi, 80) = (word64)(rdx);
    cf = _subborrow_u64(cf, rcx, WC_L64(rsi, 88), (unsigned long long*)&rcx);
    rdx = (word64)(WC_L64(rdi, 96));
    WC_S64(rdi, 88) = (word64)(rcx);
    cf = _subborrow_u64(cf, rdx, WC_L64(rsi, 96), (unsigned long long*)&rdx);
    rcx = (word64)(WC_L64(rdi, 104));
    WC_S64(rdi, 96) = (word64)(rdx);
    cf = _subborrow_u64(cf, rcx, WC_L64(rsi, 104), (unsigned long long*)&rcx);
    rdx = (word64)(WC_L64(rdi, 112));
