    r8 = (word64)(WC_L64(rsi, 8));
    WC_S64(rdi, 0) = (word64)(rcx);
    cf = _subborrow_u64(cf, r8, WC_L64(rdx, 8), (unsigned long long*)&r8);
    rcx = (word64)(WC_L64(rsi, 16));
