    cf = _subborrow_u64(cf, rcx, WC_L64(rdx, 16), (unsigned long long*)&rcx);
    r8 = (word64)(WC_L64(rsi, 24));
    WC_S64(rdi, 16) = (word64)(rcx);
    cf = _subborrow_u64(cf, r8, WC_L64(rdx, 24), (unsigned long long*)&r8);
    rcx = (word64)(WC_L64(rsi, 32));
    WC_S64(rdi, 24) = (word64)(r8);
    cf = _subborrow_u64(cf, rcx, WC_L64(rdx, 32), (unsigned long long*)&rcx);
    r8 = (word64)(WC_L64(rsi, 40));
    WC_S64(rdi, 32) = (word64)(rcx);
    cf = _subborrow_u64(cf, r8, WC_L64(rdx, 40), (unsigned long long*)&r8);
    rcx = (word64)(WC_L64(rsi, 48));
    WC_S64(rdi, 40) = (word64)(r8);
    cf = _subborrow_u64(cf, rcx, WC_L64(rdx, 48), (unsigned long long*)&rcx);
    r8 = (word64)(WC_L64(rsi, 56));
    WC_S64(rdi, 48) = (word64)(rcx);
    cf = _subborrow_u64(cf, r8, WC_L64(rdx, 56), (unsigned long long*)&r8);
    rcx = (word64)(WC_L64(rsi, 64));
