    r8 = (word64)(WC_L64(rsi, 88));
    WC_S64(rdi, 80) = (word64)(rcx);
    cf = _subborrow_u64(cf, r8, WC_L64(rdx, 88), (unsigned long long*)&r8);
    rcx = (word64)(WC_L64(rsi, 96));
    WC_S64(rdi, 88) = (word64)(r8);
    cf = _subborrow_u64(cf, rcx, WC_L64(rdx, 96), (unsigned long long*)&rcx);
    r8 = (word64)(WC_L64(rsi, 104));
    WC_S64(rdi, 96) = (word64)(rcx);
    cf = _subborrow_u64(cf, r8, WC_L64(rdx, 104), (unsigned long long*)&r8);
    rcx = (word64)(WC_L64(rsi, 112));
    WC_S64(rdi, 104) = (word64)(r8);
