    r8 = (word64)(WC_L64(rsi, 120));
    WC_S64(rdi, 112) = (word64)(rcx);
    cf = _subborrow_u64(cf, r8, WC_L64(rdx, 120), (unsigned long long*)&r8);
    rcx = (word64)(WC_L64(rsi, 128));
