    r8 = (word64)(WC_L64(rsi, 152));
    WC_S64(rdi, 144) = (word64)(rcx);
    cf = _subborrow_u64(cf, r8, WC_L64(rdx, 152), (unsigned long long*)&r8);
    rcx = (word64)(WC_L64(rsi, 160));
    WC_S64(rdi, 152) = (word64)(r8);
    cf = _subborrow_u64(cf, rcx, WC_L64(rdx, 160), (unsigned long long*)&rcx);
    r8 = (word64)(WC_L64(rsi, 168));
    WC_S64(rdi, 160) = (word64)(rcx);
    cf = _subborrow_u64(cf, r8, WC_L64(rdx, 168), (unsigned long long*)&r8);
    rcx = (word64)(WC_L64(rsi, 176));
    WC_S64(rdi, 168) = (word64)(r8);
    cf = _subborrow_u64(cf, rcx, WC_L64(rdx, 176), (unsigned long long*)&rcx);
    r8 = (word64)(WC_L64(rsi, 184));
    WC_S64(rdi, 176) = (word64)(rcx);
    cf = _subborrow_u64(cf, r8, WC_L64(rdx, 184), (unsigned long long*)&r8);
    rcx = (word64)(WC_L64(rsi, 192));
    WC_S64(rdi, 184) = (word64)(r8);
    cf = _subborrow_u64(cf, rcx, WC_L64(rdx, 192), (unsigned long long*)&rcx);
    r8 = (word64)(WC_L64(rsi, 200));
    WC_S64(rdi, 192) = (word64)(rcx);
    cf = _subborrow_u64(cf, r8, WC_L64(rdx, 200), (unsigned long long*)&r8);
    rcx = (word64)(WC_L64(rsi, 208));
    WC_S64(rdi, 200) = (word64)(r8);
    cf = _subborrow_u64(cf, rcx, WC_L64(rdx, 208), (unsigned long long*)&rcx);
    r8 = (word64)(WC_L64(rsi, 216));
    WC_S64(rdi, 208) = (word64)(rcx);
    cf = _subborrow_u64(cf, r8, WC_L64(rdx, 216), (unsigned long long*)&r8);
    rcx = (word64)(WC_L64(rsi, 224));
    WC_S64(rdi, 216) = (word64)(r8);
    cf = _subborrow_u64(cf, rcx, WC_L64(rdx, 224), (unsigned long long*)&rcx);
    r8 = (word64)(WC_L64(rsi, 232));
    WC_S64(rdi, 224) = (word64)(rcx);
    cf = _subborrow_u64(cf, r8, WC_L64(rdx, 232), (unsigned long long*)&r8);
    rcx = (word64)(WC_L64(rsi, 240));
    WC_S64(rdi, 232) = (word64)(r8);
    cf = _subborrow_u64(cf, rcx, WC_L64(rdx, 240), (unsigned long long*)&rcx);
    r8 = (word64)(WC_L64(rsi, 248));
    WC_S64(rdi, 240) = (word64)(rcx);
    cf = _subborrow_u64(cf, r8, WC_L64(rdx, 248), (unsigned long long*)&r8);
    WC_S64(rdi, 248) = (word64)(r8);
    cf = _subborrow_u64(cf, rax, rax, (unsigned long long*)&rax);
    return (sp_digit)(word64)rax;
