    WC_S64(rdi, 168) = (word64)(r8);
    cf = _subborrow_u64(cf, r9, r10, (unsigned long long*)&r9);
    r8 = (word64)(WC_L64(rdx, 184));
    r10 = (word64)(WC_L64(rsi, 184));
