    rdx = (word64)(word64)idx;

    rax = (word64)(1);
    y10 = _mm256_zextsi128_si256(_mm_cvtsi64_si128((long long)rdx));
    y11 = _mm256_zextsi128_si256(_mm_cvtsi64_si128((long long)rax));
