    y10 = _mm256_permutevar8x32_epi32(y10, y13);
    y11 = _mm256_permutevar8x32_epi32(y11, y13);
    /* START: 0-15 */
    y13 = _mm256_setzero_si256();
    y4 = _mm256_setzero_si256();
    y5 = _mm256_setzero_si256();
    y6 = _mm256_setzero_si256();
    y7 = _mm256_setzero_si256();
