    rcx = (word64)(WC_L64(rsi, 0));
    y12 = _mm256_cmpeq_epi32(y13, y10);
    y0 = _mm256_loadu_si256((const __m256i*)WC_PR(rcx, 0));
    y1 = _mm256_loadu_si256((const __m256i*)WC_PR(rcx, 32));
    y2 = _mm256_loadu_si256((const __m256i*)WC_PR(rcx, 64));
    y3 = _mm256_loadu_si256((const __m256i*)WC_PR(rcx, 96));
    y0 = _mm256_and_si256(y0, y12);
    y1 = _mm256_and_si256(y1, y12);
    y2 = _mm256_and_si256(y2, y12);
    y3 = _mm256_and_si256(y3, y12);
    y4 = _mm256_or_si256(y4, y0);
    y5 = _mm256_or_si256(y5, y1);
    y6 = _mm256_or_si256(y6, y2);
    y7 = _mm256_or_si256(y7, y3);
    y13 = _mm256_add_epi32(y13, y11);
