    WC_S64(rdi, 24) = (word64)(r8);
    rax = (word64)(WC_L64(r9, 24));
    r8 = (word64)(WC_L64(r9, 16));
    rax = (word64)(WC_X64I_BSWAP64(rax));
    r8 = (word64)(WC_X64I_BSWAP64(r8));
