    r9 = (word64)((word64)_pext_u64(r9, rcx));
    WC_S64(rdi, 16) = (word64)(r10);
    cf = _addcarry_u64(cf, r8, r9, (unsigned long long*)&r8);
    r10 = (word64)(WC_L64(rdx, 32));
    r9 = (word64)(WC_L64(rsi, 32));
    r10 = (word64)((word64)_pext_u64(r10, rcx));
    WC_S64(rdi, 24) = (word64)(r8);
    cf = _addcarry_u64(cf, r9, r10, (unsigned long long*)&r9);
    r8 = (word64)(WC_L64(rdx, 40));
    r10 = (word64)(WC_L64(rsi, 40));
    r8 = (word64)((word64)_pext_u64(r8, rcx));
    WC_S64(rdi, 32) = (word64)(r9);
    cf = _addcarry_u64(cf, r10, r8, (unsigned long long*)&r10);
