    cf = _addcarry_u64(0, r13, rcx, (unsigned long long*)&r13);
    cf = _addcarry_u64(cf, r14, r8, (unsigned long long*)&r14);
    cf = _addcarry_u64(cf, r15, r9, (unsigned long long*)&r15);
    cf = _addcarry_u64(cf, rsi, 0, (unsigned long long*)&rsi);
    cf = _addcarry_u64(cf, rbx, 0, (unsigned long long*)&rbx);
    cf = _addcarry_u64(cf, rbp, 0, (unsigned long long*)&rbp);
