    cf = _subborrow_u64(cf, rbp, r8, (unsigned long long*)&rbp);
    cf = _subborrow_u64(cf, r11, r9, (unsigned long long*)&r11);
    cf = _subborrow_u64(cf, r12, r10, (unsigned long long*)&r12);
    cf = _subborrow_u64(cf, r13, r10, (unsigned long long*)&r13);
