    r11 = (word64)(r13);
    r11 = (word64)(r11 * rcx);
    /* a[i+0] += m[0] * mu */
    rax = (word64)(r11);
    r10 = (word64)(0);
    WC_X64I_MUL128(rax, rdx, rax, WC_L64(rsi, 0));
    cf = _addcarry_u64(0, r13, rax, (unsigned long long*)&r13);
    cf = _addcarry_u64(cf, r10, rdx, (unsigned long long*)&r10);
    /* a[i+1] += m[1] * mu */
    rax = (word64)(r11);
    r9 = (word64)(0);
    WC_X64I_MUL128(rax, rdx, rax, WC_L64(rsi, 8));
    r13 = (word64)(r14);
    cf = _addcarry_u64(0, r13, rax, (unsigned long long*)&r13);
    cf = _addcarry_u64(cf, r9, rdx, (unsigned long long*)&r9);
    cf = _addcarry_u64(0, r13, r10, (unsigned long long*)&r13);
    cf = _addcarry_u64(cf, r9, 0, (unsigned long long*)&r9);
    /* a[i+2] += m[2] * mu */
    rax = (word64)(r11);
    r10 = (word64)(0);
    WC_X64I_MUL128(rax, rdx, rax, WC_L64(rsi, 16));
    r14 = (word64)(WC_L64(rdi, 16));
    cf = _addcarry_u64(0, r14, rax, (unsigned long long*)&r14);
    cf = _addcarry_u64(cf, r10, rdx, (unsigned long long*)&r10);
    cf = _addcarry_u64(0, r14, r9, (unsigned long long*)&r14);
    cf = _addcarry_u64(cf, r10, 0, (unsigned long long*)&r10);
    /* a[i+3] += m[3] * mu */
    rax = (word64)(r11);
    r9 = (word64)(0);
    WC_X64I_MUL128(rax, rdx, rax, WC_L64(rsi, 24));
    r12 = (word64)(WC_L64(rdi, 24));
    cf = _addcarry_u64(0, r12, rax, (unsigned long long*)&r12);
    cf = _addcarry_u64(cf, r9, rdx, (unsigned long long*)&r9);
    cf = _addcarry_u64(0, r12, r10, (unsigned long long*)&r12);
    WC_S64(rdi, 24) = (word64)(r12);
    cf = _addcarry_u64(cf, r9, 0, (unsigned long long*)&r9);
    /* a[i+4] += m[4] * mu */
    rax = (word64)(r11);
    r10 = (word64)(0);
    WC_X64I_MUL128(rax, rdx, rax, WC_L64(rsi, 32));
    r12 = (word64)(WC_L64(rdi, 32));
    cf = _addcarry_u64(0, r12, rax, (unsigned long long*)&r12);
    cf = _addcarry_u64(cf, r10, rdx, (unsigned long long*)&r10);
    cf = _addcarry_u64(0, r12, r9, (unsigned long long*)&r12);
    WC_S64(rdi, 32) = (word64)(r12);
    cf = _addcarry_u64(cf, r10, 0, (unsigned long long*)&r10);
    /* a[i+5] += m[5] * mu */
    rax = (word64)(r11);
    WC_X64I_MUL128(rax, rdx, rax, WC_L64(rsi, 40));
    r12 = (word64)(WC_L64(rdi, 40));
    cf = _addcarry_u64(0, r10, rax, (unsigned long long*)&r10);
    cf = _addcarry_u64(cf, rdx, r15, (unsigned long long*)&rdx);
    r15 = (word64)(0);
    cf = _addcarry_u64(cf, r15, 0, (unsigned long long*)&r15);
    cf = _addcarry_u64(0, r12, r10, (unsigned long long*)&r12);
    WC_S64(rdi, 40) = (word64)(r12);
