    cf = _subborrow_u64(cf, rcx, r13, (unsigned long long*)&rcx);
    cf = _subborrow_u64(cf, r8, r14, (unsigned long long*)&r8);
    cf = _subborrow_u64(cf, r9, rsi, (unsigned long long*)&r9);
    cf = _subborrow_u64(cf, r10, rsi, (unsigned long long*)&r10);
    cf = _subborrow_u64(cf, r11, rsi, (unsigned long long*)&r11);
