    unsigned char cf;

    rdi = (word64)(size_t)a;
    rsi = (word64)(size_t)b;

    rdx = (word64)(WC_L64(rsi, 0));
    rcx = (word64)(WC_L64(rsi, 8));
    r8 = (word64)(WC_L64(rsi, 16));
    r9 = (word64)(WC_L64(rsi, 24));
    r10 = (word64)(WC_L64(rsi, 32));
    r11 = (word64)(WC_L64(rsi, 40));
    cf = _subborrow_u64(0, WC_L64(rdi, 0), rdx, (unsigned long long*)&WC_S64(
        rdi, 0));
