    rdx = (word64)(WC_L64(rsi, 0));
    rax = (word64)(WC_L64(rsi, 8));
    rcx = (word64)(WC_L64(rsi, 16));
    r8 = (word64)(WC_L64(rsi, 24));
    r9 = (word64)(WC_L64(rsi, 32));
    r10 = (word64)(WC_L64(rsi, 40));
