    rax = (word64)((rax >> 1) | (rcx << 63));
    rcx = (word64)((rcx >> 1) | (r8 << 63));
    r8 = (word64)((r8 >> 1) | (r9 << 63));
    r9 = (word64)((r9 >> 1) | (r10 << 63));
    r10 = (word64)(r10 >> 1);
