    cf = _addcarry_u64(cf, r8, r14, (unsigned long long*)&r8);
    cf = _addcarry_u64(cf, r9, r15, (unsigned long long*)&r9);
    cf = _addcarry_u64(cf, r10, rbx, (unsigned long long*)&r10);
    cf = _addcarry_u64(cf, r11, rbp, (unsigned long long*)&r11);
