    cf = _addcarry_u64(0, r12, rax, (unsigned long long*)&r12);
    cf = _addcarry_u64(cf, r9, rdx, (unsigned long long*)&r9);
    cf = _addcarry_u64(0, r12, r10, (unsigned long long*)&r12);
    WC_S64(rdi, 104) = (word64)(r12);
    cf = _addcarry_u64(cf, r9, 0, (unsigned long long*)&r9);
    /* a[i+14] += m[14] * mu */
    rax = (word64)(r11);
    r10 = (word64)(0);
    WC_X64I_MUL128(rax, rdx, rax, WC_L64(rsi, 112));
